corpus_block("test-scale-date.R: inherits timezone from data", {
  base_time <- function(tz = "") {
    as.POSIXct(strptime("2015-06-01", "%Y-%m-%d", tz = tz))
  }
  df <- data_frame(
    time1 = base_time("") + 0:6 * 3600,
    time2 = base_time("UTC") + 0:6 * 3600,
    time3 = base_time("Australia/Lord_Howe") + (0:6 + 13) * 3600, # has half hour offset
    y = seq_along(base_time)
  )
  .plot("test-scale-date.R: inherits timezone from data #1", p <- ggplot(df, aes(y = y)) + geom_point(aes(time1)))
  sc <- get_panel_scales(p)$x
  .plot("test-scale-date.R: inherits timezone from data #2", p <- ggplot(df, aes(y = y)) + geom_point(aes(time2)))
  sc <- get_panel_scales(p)$x
})

corpus_block("test-scale-date.R: first timezone wins", {
  base_time <- function(tz = "") {
    as.POSIXct(strptime("2015-06-01", "%Y-%m-%d", tz = tz))
  }
  df <- data_frame(
    time1 = base_time("") + 0:6 * 3600,
    time2 = base_time("UTC") + 0:6 * 3600,
    time3 = base_time("Australia/Lord_Howe") + (0:6 + 13) * 3600, # has half hour offset
    y = seq_along(base_time)
  )
  .plot("test-scale-date.R: first timezone wins #1", p <- ggplot(df, aes(y = y)) +
      geom_point(aes(time2)) +
      geom_point(aes(time3), colour = "red") +
      scale_x_datetime(date_breaks = "hour", date_labels = "%H:%M"))
  sc <- get_panel_scales(p)$x
})

